import com.joebywan.daybook.core.PuzzleType
import com.joebywan.daybook.puzzles.Shikaku
import com.joebywan.daybook.puzzles.ShikakuState
import com.joebywan.daybook.puzzles.Snap
import com.joebywan.daybook.puzzles.SnapState
import com.joebywan.daybook.puzzles.Sudoku
import com.joebywan.daybook.puzzles.SudokuState
import org.junit.Assert.assertEquals
import org.junit.Test
import java.time.LocalDate

/**
 * Pins Shikaku, Snap and Sudoku boards so the web build can be diffed against the app.
 *
 * The web page prints lines in exactly this format under `?dump`; [WebParityDumpTest] writes the
 * JVM's side of a whole year, which is what the JVM-before/after and JVM-vs-wasm diffs are taken from.
 */
class WebParityShikakuSnapSudokuTest {

    @Test
    fun `Shikaku, Snap and Sudoku boards are pinned for the web parity check`() {
        val lines = PARITY_DATES.flatMap { date -> PUZZLES.flatMap { p -> Difficulty.entries.map { fingerprint(p, date, it) } } }
        lines.forEach(::println)
        assertEquals(FINGERPRINTS, lines)
    }

    private fun fingerprint(p: PuzzleType, date: LocalDate, tier: Difficulty): String {
        val seed = DailySeed.seedFor(date, p.id, tier)
        val body = when (val s = p.generate(seed, tier)) {
            is ShikakuState -> "${s.width}x${s.height} clues=" +
                s.clues.joinToString(",") { it?.toString() ?: "." } +
                " blocks=" + s.solution.joinToString(";") { "${it.r0},${it.c0},${it.r1},${it.c1}" }
            is SnapState -> "${s.width}x${s.height} waypoints=${s.waypoints.joinToString(",")}"
            is SudokuState -> "givens=" + s.cells.joinToString("") + " solution=" + s.solution.joinToString("")
            else -> error("unexpected state $s")
        }
        return "${p.id} $date ${tier.name} seed=$seed $body"
    }

